def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 3 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    desperate_opp = False
    rich_aggro_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_opp = True
        if opp.get('budget', 0) > 900:
            rich_aggro_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    if hp <= 2 or no_water >= 2:
        target = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif hp <= 4 or no_water >= 1:
        target = max(DAILY_SALARY * 0.78, highest_prev + 1.5)
    else:
        base = DAILY_SALARY * (0.38 + 0.18 * scarcity)
        if highest_prev >= 110:
            target = DAILY_SALARY * 0.32
        elif highest_prev >= 85:
            target = DAILY_SALARY * 0.42
        elif highest_prev > 0:
            target = max(base, min(highest_prev + 1.0, DAILY_SALARY * 0.72))
        else:
            target = base

    if desperate_opp and hp > 4 and no_water == 0:
        target *= 0.9
    if rich_aggro_count >= 2 and hp > 4 and no_water == 0:
        target *= 0.88

    if supply >= 23 and hp > 4:
        target *= 0.9
    elif supply <= 17:
        target *= 1.08

    if avg_prev >= 95 and hp > 4 and no_water == 0:
        target *= 0.9

    reserve = 0.0
    if hp > 4 and no_water == 0:
        reserve = DAILY_SALARY * 1.2
    elif hp > 2:
        reserve = DAILY_SALARY * 0.5

    cap = max(0.0, budget - reserve)
    if hp <= 2 or no_water >= 2:
        cap = budget

    bid = min(target, cap if cap > 0 else budget)
    bid = max(0.0, min(bid, budget))

    if hp > 5 and no_water == 0 and highest_prev >= 120:
        bid = min(bid, DAILY_SALARY * 0.28)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids to infer aggressiveness
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else 0.0

    # Estimate how many full water units are likely needed to stay safe.
    # If supply is tight, bidding more increases chance to secure at least one unit.
    # Use a conservative target tied to supply.
    supply_units = supply / float(WATER_REQ)
    # Convert to an integer index-like quantity safely.
    # (Used only for thresholds, not for list indexing.)
    if supply_units < 1.2:
        supply_pressure = 0.9
    elif supply_units < 1.8:
        supply_pressure = 0.7
    else:
        supply_pressure = 0.55

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # If I'm already in danger (low hp or accumulating no-water days), bid aggressively.
    if my_hp <= 2.0 or no_water_days >= 2:
        bid = DAILY_SALARY * (0.85 + 0.1 * supply_pressure)
        return float(min(my_budget, bid))

    # If an opponent was extremely aggressive yesterday, avoid mirroring their cost.
    # Instead, bid enough to compete but not enough to waste budget.
    if highest_prev_bid >= DAILY_SALARY * 1.05:
        # Cindy-like behavior; keep mid-high to beat overbidding opponents when possible.
        bid = DAILY_SALARY * (0.55 * supply_pressure + 0.25)
        # If second-highest was also high, slightly increase.
        if second_prev_bid >= DAILY_SALARY * 0.9:
            bid = bid * 1.15
        return float(min(my_budget, bid))

    # Otherwise, bid moderately based on supply pressure and day.
    # Slightly increasing over time to prevent late starvation.
    time_factor = 1.0 + min(0.15, (day / 10.0) * 0.15)
    bid = DAILY_SALARY * (0.45 * supply_pressure + 0.25) * time_factor

    # Ensure we don't bid too low when supply is near minimum.
    if supply <= MIN_SUPPLY + 0.5:
        bid = max(bid, DAILY_SALARY * 0.5)

    return float(min(my_budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    # If supply is less than my requirement, I cannot get water. Bid 0 to save budget.
    if day_context['supply'] < WATER_REQ:
        return 0.0

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no alive opponents, bid minimally to get water
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid_amount = 0.0 # Initialize bid_amount

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # Determine how many agents can potentially get water
        num_possible_winners = int(day_context['supply'] // WATER_REQ)

        # Critical HP: Bid very high to survive
        if my_status['hp'] <= 3:
            bid_amount = max(DAILY_SALARY * 0.95, highest_prev_bid + 5)
        # Low HP: Bid high
        elif my_status['hp'] <= 5:
            bid_amount = max(DAILY_SALARY * 0.85, highest_prev_bid + 3)
        # Healthy HP: Be strategic
        else:
            if highest_prev_bid >= DAILY_SALARY * 0.8: # Opponents were very aggressive
                # If supply is scarce, still need to be competitive
                if num_possible_winners < len(alive_opponents) + 1: 
                    bid_amount = max(DAILY_SALARY * 0.7, highest_prev_bid + 1)
                else: # Enough for everyone, try to get it cheaper
                    bid_amount = max(DAILY_SALARY * 0.5, highest_prev_bid * 0.9)
            else: # Opponents were moderate or low
                if num_possible_winners > len(alive_opponents): # More slots than agents, bid low
                    bid_amount = DAILY_SALARY * 0.2
                elif num_possible_winners >= 1: # Competitive, bid slightly above
                    bid_amount = max(DAILY_SALARY * 0.4, highest_prev_bid + 1)
                else: # Fallback, should not happen if supply >= WATER_REQ
                    bid_amount = DAILY_SALARY * 0.1 
    else: # No previous bids available (e.g., Day 1, or all opponents were eliminated/didn't bid)
        if my_status['hp'] <= 3:
            bid_amount = DAILY_SALARY * 0.9
        elif my_status['hp'] <= 5:
            bid_amount = DAILY_SALARY * 0.7
        else:
            # First day or no bids, and healthy. Bid moderately.
            num_possible_winners = int(day_context['supply'] // WATER_REQ)
            if num_possible_winners > len(alive_opponents):
                 bid_amount = DAILY_SALARY * 0.2
            else:
                 bid_amount = DAILY_SALARY * 0.55

    final_bid = min(my_status['budget'], bid_amount)
    return max(0.0, final_bid)
